<?php
if (session_status() === PHP_SESSION_NONE) session_start();
require_once __DIR__ . '/../../config/db.php';
require_once __DIR__ . '/../../core/_activity_editor_template.php';
require_once __DIR__ . '/../../core/cloudinary_upload.php';

if (!empty($_SESSION['student_logged'])) { header('Location: /lessons/lessons/academic/student_dashboard.php?error=access_denied'); exit; }
if (empty($_SESSION['academic_logged']) && empty($_SESSION['admin_logged'])) { header('Location: /lessons/lessons/academic/login.php'); exit; }

$activityId = trim((string)($_GET['id'] ?? ''));
$unit = trim((string)($_GET['unit'] ?? ''));
if ($unit === '' && $activityId !== '') {
    $s=$pdo->prepare('SELECT unit_id FROM activities WHERE id=:id LIMIT 1'); $s->execute(['id'=>$activityId]);
    $r=$s->fetch(PDO::FETCH_ASSOC); $unit=$r?(string)($r['unit_id']??''):'';
}
if ($unit==='') die('Unit not specified');

function ddpe_h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function ddpe_item(array $i,int $fallbackLayer=0):?array{
    $id=(int)($i['id']??0); $url=trim((string)($i['pic_url']??'')); $label=trim((string)($i['label']??'')); if($id<=0||($url===''&&$label===''))return null;
    return ['id'=>$id,'pic_url'=>$url,'label'=>$label,'x'=>max(0,min(96,(float)($i['x']??10))),'y'=>max(0,min(96,(float)($i['y']??10))),'w'=>max(4,min(60,(float)($i['w']??14))),'h'=>max(4,min(60,(float)($i['h']??12))),'rot'=>(((int)($i['rot']??0))%360+360)%360,'flipH'=>!empty($i['flipH']),'layer'=>max(0,(int)($i['layer']??$fallbackLayer))];
}
function ddpe_block(array $b,int $n):array{
    $items=[]; foreach(($b['items']??[]) as $k=>$i){if(is_array($i)&&($x=ddpe_item($i,$k)))$items[]=$x;}
    usort($items,fn($a,$c)=>$a['layer']<=>$c['layer']); foreach($items as $k=>&$i)$i['layer']=$k; unset($i);
    return ['id'=>trim((string)($b['id']??''))?:('block_'.$n),'title'=>trim((string)($b['title']??''))?:('Block '.$n),'instructions'=>trim((string)($b['instructions']??'')),'background_image'=>trim((string)($b['background_image']??'')),'items'=>$items];
}
function ddpe_payload($raw):array{
    $d=is_string($raw)?json_decode($raw,true):$raw; if(!is_array($d))$d=[];
    $blocks=[];
    if(!empty($d['blocks'])&&is_array($d['blocks'])) foreach($d['blocks'] as $k=>$b) if(is_array($b)) $blocks[]=ddpe_block($b,$k+1);
    if(!$blocks && (!empty($d['background_image'])||!empty($d['items']))) $blocks[]=ddpe_block(['title'=>'Block 1','instructions'=>$d['instructions']??'','background_image'=>$d['background_image']??'','items'=>$d['items']??[]],1);
    if(!$blocks)$blocks[]=ddpe_block([],1);
    return ['title'=>trim((string)($d['title']??''))?:'Drag & Drop Picture','instructions'=>trim((string)($d['instructions']??'')),'blocks'=>$blocks];
}

if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='upload_pic_item'){
    header('Content-Type: application/json; charset=utf-8');
    if(empty($_FILES['image']['tmp_name'])||!is_uploaded_file($_FILES['image']['tmp_name'])){echo json_encode(['error'=>'No file received']);exit;}
    $url=upload_to_cloudinary($_FILES['image']['tmp_name']); echo $url?json_encode(['url'=>$url]):json_encode(['error'=>'Upload failed']); exit;
}

$error='';$saved=false;$data=['title'=>'Drag & Drop Picture','instructions'=>'','blocks'=>[ddpe_block([],1)]];
if($activityId!==''){
    $s=$pdo->prepare("SELECT data FROM activities WHERE id=:id AND type='dragdrop_pic' LIMIT 1");$s->execute(['id'=>$activityId]);$r=$s->fetch(PDO::FETCH_ASSOC);if($r)$data=ddpe_payload($r['data']??null);
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    $title=trim((string)($_POST['activity_title']??''));$instructions=trim((string)($_POST['activity_instructions']??''));
    $raw=json_decode((string)($_POST['blocks_json']??'[]'),true);if(!is_array($raw))$raw=[];
    $blocks=[];foreach($raw as $k=>$b)if(is_array($b))$blocks[]=ddpe_block($b,$k+1);
    $valid=array_values(array_filter($blocks,fn($b)=>$b['background_image']!==''&&!empty($b['items'])));
    if(!$valid)$error='Add at least one complete block with a background and label or picture zones.';
    elseif(count($valid)!==count($blocks))$error='Every block needs a background and at least one label or picture.';
    else{
        $payload=json_encode(['title'=>$title?:'Drag & Drop Picture','instructions'=>$instructions,'blocks'=>$valid],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        if($activityId!==''){$s=$pdo->prepare("UPDATE activities SET data=:data WHERE id=:id AND type='dragdrop_pic'");$s->execute(['data'=>$payload,'id'=>$activityId]);}
        else{$s=$pdo->prepare("INSERT INTO activities (unit_id,type,data) VALUES (:unit,'dragdrop_pic',:data)");$s->execute(['unit'=>$unit,'data'=>$payload]);$activityId=(string)$pdo->lastInsertId();}
        $saved=true;$data=['title'=>$title?:'Drag & Drop Picture','instructions'=>$instructions,'blocks'=>$valid];
    }
}

ob_start();
?>
<style>
.ddpe-grid{display:grid;grid-template-columns:330px minmax(0,1fr);gap:18px;align-items:start}@media(max-width:920px){.ddpe-grid{grid-template-columns:1fr}}.ddpe-card,.ddpe-main{background:#fff;border:1px solid #e4e1f4;border-radius:18px;padding:15px;box-shadow:0 6px 18px rgba(31,41,55,.06)}.ddpe-side{display:flex;flex-direction:column;gap:12px}.ddpe-card label{display:block;margin:0 0 5px;font-size:12px;font-weight:800;color:#6d64c6;text-transform:uppercase}.ddpe-card input[type=text],.ddpe-card textarea{width:100%;box-sizing:border-box;border:1px solid #cfc9ee;border-radius:10px;padding:9px 11px;font:inherit}.ddpe-card textarea{min-height:72px;resize:vertical}.ddpe-tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.ddpe-tab{border:1px solid #cfc9ee;background:#fff;color:#5b53aa;border-radius:999px;padding:8px 12px;font-weight:800;cursor:pointer}.ddpe-tab.active{background:#7F77DD;color:#fff}.ddpe-add{border-style:dashed}.ddpe-block-actions{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.ddpe-mini{border:1px solid #cfc9ee;background:#fff;color:#5b53aa;border-radius:8px;padding:5px 8px;font-size:11px;font-weight:800;cursor:pointer}.ddpe-mini.danger{color:#dc2626;border-color:#fecaca}.ddpe-list{list-style:none;padding:0;margin:9px 0 0;display:flex;flex-direction:column;gap:8px}.ddpe-item{display:grid;grid-template-columns:24px 50px minmax(0,1fr) 28px;gap:7px;align-items:center;padding:8px;border:1px solid #e2e8f0;border-radius:12px;background:#f8fafc}.ddpe-badge{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:#7F77DD;color:#fff;font-size:11px;font-weight:800}.ddpe-thumb{width:50px;height:50px;border-radius:7px;border:1px solid #e2e8f0;object-fit:contain;background:#fff}.ddpe-placeholder{display:grid;place-items:center;font-size:20px}.ddpe-item-main{display:flex;flex-direction:column;gap:4px;min-width:0}.ddpe-item-main input[type=text]{border:0;background:transparent;padding:2px 0;font-size:18px;line-height:1.3;font-weight:800;outline:none}.ddpe-item-main input[type=file]{font-size:10px;max-width:145px}.ddpe-actions{display:flex;gap:3px;flex-wrap:wrap}.ddpe-delete{border:0;background:transparent;color:#dc2626;font-size:21px;cursor:pointer}.ddpe-canvas-wrap{position:relative;min-height:280px;border:2px dashed #cfc9ee;border-radius:16px;background:#f8fafc;overflow:hidden;display:flex;align-items:center;justify-content:center}.ddpe-canvas-wrap.has-image{border-style:solid}.ddpe-bg{display:block;max-width:100%;height:auto;pointer-events:none;user-select:none}.ddpe-overlay{position:absolute;z-index:5;touch-action:none}.ddpe-empty{padding:50px 20px;text-align:center;color:#64748b;font-weight:700}.ddpe-zone{position:absolute;box-sizing:border-box;border:2px solid #7F77DD;border-radius:9px;background:rgba(127,119,221,.14);cursor:grab;touch-action:none}.ddpe-zone.selected{border-color:#F97316;background:rgba(249,115,22,.16);z-index:999!important}.ddpe-zone img{width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;transform-origin:center}.ddpe-num{position:absolute;left:-9px;top:-9px;width:21px;height:21px;border-radius:50%;display:grid;place-items:center;background:#7F77DD;color:#fff;font-size:11px;font-weight:800}.ddpe-resize{position:absolute;right:-7px;bottom:-7px;width:15px;height:15px;border-radius:4px;background:#F97316;cursor:nwse-resize;touch-action:none}.ddpe-save{border:0;border-radius:12px;padding:12px 24px;background:#16a34a;color:#fff;font-weight:800;font-size:15px;cursor:pointer}.ddpe-alert{border-radius:11px;padding:10px 12px;margin-bottom:12px;font-weight:700}.ddpe-alert.error{background:#fee2e2;color:#991b1b}.ddpe-alert.success{background:#dcfce7;color:#166534}.ddpe-note{font-size:12px;color:#64748b;line-height:1.4}
</style>
<?php if($error):?><div class="ddpe-alert error"><?=ddpe_h($error)?></div><?php endif;?><?php if($saved):?><div class="ddpe-alert success">Activity saved successfully.</div><?php endif;?>
<form id="ddpeForm" method="post"><input type="hidden" name="blocks_json" id="blocksJson">
<div class="ddpe-grid"><aside class="ddpe-side">
<section class="ddpe-card"><label>Activity title</label><input type="text" name="activity_title" value="<?=ddpe_h($data['title'])?>"><label style="margin-top:10px">General instructions</label><textarea name="activity_instructions"><?=ddpe_h($data['instructions'])?></textarea></section>
<section class="ddpe-card"><label>Current block</label><input type="text" id="blockTitle" placeholder="Block title"><label style="margin-top:10px">Block instructions</label><textarea id="blockInstructions"></textarea><label style="margin-top:10px">Background image</label><input type="file" id="blockBgFile" accept="image/*"><p class="ddpe-note">Click or tap the scene to add a zone. Each zone can use a written label or a picture.</p></section>
<section class="ddpe-card"><label>Label or picture zones and layer order</label><ul class="ddpe-list" id="itemList"></ul><p class="ddpe-note" id="noItems">No zones yet.</p></section><button class="ddpe-save" type="submit">Save Activity</button></aside>
<main class="ddpe-main"><div class="ddpe-tabs" id="blockTabs"></div><div class="ddpe-block-actions"><button type="button" class="ddpe-mini" id="duplicateBlock">Duplicate block</button><button type="button" class="ddpe-mini" id="moveBlockLeft">Move left</button><button type="button" class="ddpe-mini" id="moveBlockRight">Move right</button><button type="button" class="ddpe-mini danger" id="deleteBlock">Delete block</button></div><div class="ddpe-canvas-wrap" id="canvasWrap"><div class="ddpe-empty" id="emptyHint">Upload a background image to begin.</div><img class="ddpe-bg" id="edBg" alt="Background preview" style="display:none"><div class="ddpe-overlay" id="overlay"></div></div></main></div></form>
<script>
(function(){'use strict';
let blocks=<?=json_encode($data['blocks'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,active=0,selectedId=null,pending=0;
const tabs=document.getElementById('blockTabs'),title=document.getElementById('blockTitle'),instructions=document.getElementById('blockInstructions'),bgFile=document.getElementById('blockBgFile'),wrap=document.getElementById('canvasWrap'),bg=document.getElementById('edBg'),overlay=document.getElementById('overlay'),empty=document.getElementById('emptyHint'),list=document.getElementById('itemList'),noItems=document.getElementById('noItems'),form=document.getElementById('ddpeForm'),out=document.getElementById('blocksJson');
function uid(){return'block_'+Date.now()+'_'+Math.random().toString(36).slice(2,7)}function block(){return blocks[active]}function normalize(b){b.items.forEach((x,i)=>x.layer=i)}function nextId(b){return b.items.reduce((m,x)=>Math.max(m,Number(x.id)||0),0)+1}function tr(i){return`rotate(${Number(i.rot)||0}deg) scaleX(${i.flipH?-1:1})`}
function sync(){if(!bg.complete||!bg.naturalWidth)return;const wr=wrap.getBoundingClientRect(),ir=bg.getBoundingClientRect();overlay.style.left=(ir.left-wr.left)+'px';overlay.style.top=(ir.top-wr.top)+'px';overlay.style.width=ir.width+'px';overlay.style.height=ir.height+'px'}
function setBg(src){if(!src){bg.style.display='none';empty.style.display='block';wrap.classList.remove('has-image');overlay.innerHTML='';return}bg.onload=()=>{sync();renderZones()};bg.src=src;bg.style.display='block';empty.style.display='none';wrap.classList.add('has-image')}
function upload(file,cb){pending++;const fd=new FormData();fd.append('action','upload_pic_item');fd.append('image',file);fetch(location.href,{method:'POST',body:fd,credentials:'same-origin'}).then(r=>r.json()).then(d=>{if(!d.url)throw new Error(d.error||'Upload failed');cb(d.url)}).catch(e=>alert(e.message)).finally(()=>pending--)}
function renderTabs(){tabs.innerHTML='';blocks.forEach((b,i)=>{const x=document.createElement('button');x.type='button';x.className='ddpe-tab'+(i===active?' active':'');x.textContent=(i+1)+'. '+(b.title||('Block '+(i+1)));x.onclick=()=>{saveFields();active=i;selectedId=null;render()};tabs.appendChild(x)});const add=document.createElement('button');add.type='button';add.className='ddpe-tab ddpe-add';add.textContent='+ Add block';add.onclick=()=>{saveFields();blocks.push({id:uid(),title:'Block '+(blocks.length+1),instructions:'',background_image:'',items:[]});active=blocks.length-1;selectedId=null;render()};tabs.appendChild(add)}
function saveFields(){const b=block();if(!b)return;b.title=title.value.trim()||('Block '+(active+1));b.instructions=instructions.value}
function zoneEl(item){const z=document.createElement('div');z.className='ddpe-zone'+(selectedId===item.id?' selected':'');z.dataset.id=item.id;Object.assign(z.style,{left:item.x+'%',top:item.y+'%',width:item.w+'%',height:item.h+'%',zIndex:String(10+item.layer)});const n=document.createElement('div');n.className='ddpe-num';n.textContent=item.id;z.appendChild(n);if(item.pic_url){const im=document.createElement('img');im.src=item.pic_url;im.style.transform=tr(item);z.appendChild(im)}const h=document.createElement('div');h.className='ddpe-resize';z.appendChild(h);z.addEventListener('pointerdown',e=>{if(e.target===h)return;e.preventDefault();selectedId=item.id;renderZones();const a=overlay.querySelector(`[data-id="${item.id}"]`),r=overlay.getBoundingClientRect(),s={x:e.clientX,y:e.clientY,ix:item.x,iy:item.y};a.setPointerCapture(e.pointerId);const mv=v=>{item.x=Math.max(0,Math.min(100-item.w,s.ix+(v.clientX-s.x)/r.width*100));item.y=Math.max(0,Math.min(100-item.h,s.iy+(v.clientY-s.y)/r.height*100));a.style.left=item.x+'%';a.style.top=item.y+'%'};const up=()=>{a.removeEventListener('pointermove',mv);a.removeEventListener('pointerup',up);a.removeEventListener('pointercancel',up)};a.addEventListener('pointermove',mv);a.addEventListener('pointerup',up);a.addEventListener('pointercancel',up)});h.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();h.setPointerCapture(e.pointerId);const r=overlay.getBoundingClientRect(),s={x:e.clientX,y:e.clientY,w:item.w,h:item.h};const mv=v=>{item.w=Math.max(4,Math.min(60,100-item.x,s.w+(v.clientX-s.x)/r.width*100));item.h=Math.max(4,Math.min(60,100-item.y,s.h+(v.clientY-s.y)/r.height*100));z.style.width=item.w+'%';z.style.height=item.h+'%'};const up=()=>{h.removeEventListener('pointermove',mv);h.removeEventListener('pointerup',up);h.removeEventListener('pointercancel',up)};h.addEventListener('pointermove',mv);h.addEventListener('pointerup',up);h.addEventListener('pointercancel',up)});return z}
function renderZones(){sync();overlay.innerHTML='';normalize(block());block().items.forEach(i=>overlay.appendChild(zoneEl(i)))}
function renderList(){list.innerHTML='';noItems.style.display=block().items.length?'none':'block';block().items.forEach((item,index)=>{const li=document.createElement('li');li.className='ddpe-item';const badge=document.createElement('div');badge.className='ddpe-badge';badge.textContent=item.id;let thumb;if(item.pic_url){thumb=document.createElement('img');thumb.className='ddpe-thumb';thumb.src=item.pic_url;thumb.style.transform=tr(item)}else{thumb=document.createElement('div');thumb.className='ddpe-thumb ddpe-placeholder';thumb.textContent=item.label?'Aa':'📷'}const main=document.createElement('div');main.className='ddpe-item-main';const label=document.createElement('input');label.type='text';label.value=item.label||'';label.placeholder='Type a label or add an image';label.oninput=()=>item.label=label.value;const file=document.createElement('input');file.type='file';file.accept='image/*';file.onchange=()=>file.files[0]&&upload(file.files[0],u=>{item.pic_url=u;render()});const acts=document.createElement('div');acts.className='ddpe-actions';[['↻',()=>{item.rot=(item.rot+90)%360;render()}],['↔',()=>{item.flipH=!item.flipH;render()}],['↑',()=>moveItem(index,1)],['↓',()=>moveItem(index,-1)]].forEach(([t,f])=>{const b=document.createElement('button');b.type='button';b.className='ddpe-mini';b.textContent=t;b.onclick=f;acts.appendChild(b)});main.append(label,file,acts);const del=document.createElement('button');del.type='button';del.className='ddpe-delete';del.textContent='×';del.onclick=()=>{block().items.splice(index,1);normalize(block());render()};li.append(badge,thumb,main,del);list.appendChild(li)})}
function moveItem(i,d){const j=i+d;if(j<0||j>=block().items.length)return;[block().items[i],block().items[j]]=[block().items[j],block().items[i]];normalize(block());render()}
function render(){renderTabs();title.value=block().title||('Block '+(active+1));instructions.value=block().instructions||'';setBg(block().background_image||'');renderList();renderZones()}
overlay.addEventListener('pointerdown',e=>{if(e.target!==overlay||!bg.naturalWidth)return;e.preventDefault();const r=overlay.getBoundingClientRect(),w=14,h=12,x=Math.max(0,Math.min(100-w,(e.clientX-r.left)/r.width*100-w/2)),y=Math.max(0,Math.min(100-h,(e.clientY-r.top)/r.height*100-h/2)),item={id:nextId(block()),pic_url:'',label:'',x,y,w,h,rot:0,flipH:false,layer:block().items.length};block().items.push(item);selectedId=item.id;render();setTimeout(()=>list.querySelector('li:last-child input[type=text]')?.focus(),0)});
bgFile.onchange=()=>{const f=bgFile.files[0];if(f)upload(f,u=>{block().background_image=u;setBg(u);renderTabs()})};title.oninput=()=>{block().title=title.value;renderTabs()};instructions.oninput=()=>block().instructions=instructions.value;
document.getElementById('duplicateBlock').onclick=()=>{saveFields();const copy=JSON.parse(JSON.stringify(block()));copy.id=uid();copy.title=(copy.title||'Block')+' Copy';blocks.splice(active+1,0,copy);active++;render()};document.getElementById('moveBlockLeft').onclick=()=>{if(active<1)return;saveFields();[blocks[active-1],blocks[active]]=[blocks[active],blocks[active-1]];active--;render()};document.getElementById('moveBlockRight').onclick=()=>{if(active>=blocks.length-1)return;saveFields();[blocks[active+1],blocks[active]]=[blocks[active],blocks[active+1]];active++;render()};document.getElementById('deleteBlock').onclick=()=>{if(blocks.length===1){alert('The activity must keep at least one block.');return}if(!confirm('Delete this block?'))return;blocks.splice(active,1);active=Math.max(0,active-1);render()};
form.onsubmit=e=>{saveFields();if(pending>0){e.preventDefault();alert('Please wait for uploads to finish.');return}if(blocks.some(b=>!b.background_image||!b.items.length||b.items.some(i=>!i.pic_url&&!i.label.trim()))){e.preventDefault();alert('Every block needs a background, and every zone needs either a label or a picture.');return}out.value=JSON.stringify(blocks)};window.addEventListener('resize',sync);render();
})();
</script>
<?php $content=ob_get_clean();render_activity_editor('Drag & Drop Picture — Editor','🖼️',$content);